mapper.select:
SELECT r.id AS region_id, r.name AS region_name, COUNT(u.id) FILTER (WHERE u.current_status = 'NORMAL') AS normal_count, COUNT(u.id) FILTER (WHERE u.current_status = 'BLOCKED') AS blocked_count, COUNT(u.id) AS total_count, AVG(rs.risk_score) AS avg_risk_score, MAX(rs.risk_score) AS max_risk_score FROM region r LEFT JOIN underpass u ON u.region_id = r.id AND u.is_deleted = FALSE LEFT JOIN LATERAL ( SELECT rs2.risk_score FROM risk_score rs2 WHERE rs2.underpass_id = u.id ORDER BY rs2.predicted_at DESC LIMIT 1 ) rs ON u.id IS NOT NULL WHERE r.is_deleted = FALSE
AND r.id = #{regionId}
GROUP BY r.id, r.name ORDER BY r.name
